SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "冯国胜", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴将，参与伏击陈友谅及追击战。", "biography": null, "status": "draft", "id": "11681f87-f6f7-58db-93b2-dad66d159d27"}, {"name": "傅友德", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "原陈友谅小孤山守将，1361年降吴。", "biography": null, "status": "draft", "id": "052c6ab9-234a-5d89-9bad-ec31f6774b50"}, {"name": "蓝玉", "aliases": ["藍玉"], "era": "明", "birth_year": null, "death_year": null, "description": "明初将领。本纪载其以都督身份随西平侯沐英征讨西番。", "biography": null, "status": "draft", "id": "b9acd0d9-69b0-5100-b509-064627c8b88a"}, {"name": "纳克楚（元太平万户）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "穆呼哩裔孙，1355年被朱俘后放北归。", "biography": null, "status": "draft", "id": "89f87003-83bd-5c55-b910-1c5e3f351489"}, {"name": "周德兴", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "吴后明左丞，1367年奉命取广西，1368年取全州。", "biography": null, "status": "draft", "id": "b38e5f86-1f46-53af-90e5-784532a2661c"}, {"name": "汤和", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年夺桥取和阳，后从朱渡江。", "biography": null, "status": "draft", "id": "76a3c1b3-e175-593d-99d7-63da30cef072"}]'::jsonb)
