id": "e90fe0b0-5648-5d8d-8e77-20d145f1f1b8"}, {"title": "明廷下诏赎回河南饥民卖出的子女", "description": "朝廷下诏，将河南百姓因饥荒卖出的子女赎回。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年四月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fefe942c-d9c4-5413-be9f-d8b4a031dfc8"}, {"title": "明廷下诏慰问并供给贫困老人", "description": "朝廷命主管官署慰问老人。八十岁以上的贫民每月给米五斗、酒三斗、肉五斤。九十岁以上者每年另给帛一匹、絮一斤。有田产者停发米。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年六月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "27470f08-19f8-5863-a7de-e5df0ae6c718"}, {"title": "明廷规定各地年长富户的礼遇", "description": "应天和凤阳八十岁以上的富户获赐社士、九十岁以上者获赐乡士。其他各地富户八十岁以上授里士、九十岁以上授社士。各等均按与县官相等的礼节相待，免除其家差役。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年六月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7f7350d0-29bd-5944-bb00-87f0da39a81e"}, {"title": "明廷向无法自给的鳏寡孤独者发米", "description": "朝廷规定，对不能自给的鳏寡孤独者每年发米六石。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年六月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8e70118b-eca6-518e-b26a-dc852691bf33"}, {"title": "明廷处分战伤士卒和阵亡将校的优恤事宜", "description": "朝廷规定，因作战受伤的士卒注销军籍，并免役三年。阵亡将校的儿子世袭时加一等品秩。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年六月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1ff97377-2a52-558f-8d87-5a347b099562"}, {"title": "明廷命以礼征聘隐居士人", "description": "朝廷命按礼节征聘隐居士人。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年六月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "105f2a3c-28e0-5050-b284-8e1d25ddd13e"}, {"title": "明廷赈济青州和郑州饥荒", "description": "青州和郑州遭遇饥荒，明廷下令赈济。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年六月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "facea162-1b12-53a0-9001-2f6fb81d975e"}, {"title": "明廷诏举通经而熟悉政务的士人", "description": "朝廷下诏荐举通晓经书、品行良好并熟悉政务的士人。六十岁以上的安排到翰林备任顾问，六十岁以下的在六部、布政使司和按察使司任用。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年七月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f6ca6ab0-2447-5d78-ab1c-add111fcc85b"}, {"title": "明廷命皇太子修祖陵", "description": "朝廷命皇太子修建泗州盱眙祖陵，并埋葬德祖以下各位帝后的礼服冠冕。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年八月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c7e8419b-ddd8-5c32-a6c9-cbb5dcbc155b"}, {"title": "明廷在云南置屯田", "description": "本纪记载，明廷于九月庚申在云南屯田。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年九月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fbc2bae0-3619-581e-bf89-50c13afaa7bc"}, {"title": "明廷定下亡故官军部分家属支领全俸规例", "description": "朝廷规定，官军亡故后若有年幼子女或年老父母，仍按原有全俸给付，并将此定为规例。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3b649b7e-3fe9-5187-a6be-18fb84f14a3a"}, {"title": "本纪记十二月初一日食", "description": "本纪记载，十二月初一出现日食。", "start_year": 1386, "end_year": 1386, "time_original": "洪武十九年十二月癸未朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5209918c-b281-57c7-9341-05edd73417ad"}, {"title": "明廷命冯胜分兵守边", "description": "朝廷命宋国公冯胜分派部队守卫边地。 按原历纪年，事情发生在公元1386至1387年之间。", "start_year": null, "end_year": null, "time_original": "洪武十九年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "218faa2a-720f-540b-ae59-486934ea6244"}, {"title": "明廷调北平等地民众运粮至大宁", "description": "朝廷征调北平、山东、山西和河南民众，将粮食运往大宁。 按原历纪年，事情发生在公元1386至1387年之间。", "start_year": null, "end_year": null, "time_original": "洪武十九年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ef8b727a-80b1-515e-ae0b-d965f17ad84a"}, {"title": "高丽等地向明廷入贡", "description": "本纪记载，当年高丽、琉球、暹罗、占城、安南向明廷入贡。 按原历纪年，事情发生在公元1386至1387年之间。", "start_year": null, "end_year": null, "time_original": "洪武十九年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "62d700c4-8fa3-5014-b3e1-9a4ec5eec53a"}, {"title": "冯胜等奉命率军征纳哈出", "description": "朝廷任命冯胜为征虏大将军，傅友德、蓝玉任副将，率军征讨纳哈出。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年正月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c5cd4de9-f8ea-54a4-af08-b8aa170c0963"}, {"title": "明廷烧毁锦衣卫刑具并移送囚犯", "description": "朝廷命烧毁锦衣卫的刑具，把被关押的囚犯交给刑部。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "527dd3b5-bbb5-5ac5-80e1-3cffa61512cf"}, {"title": "明廷在南郊祭祀天地", "description": "明廷于正月甲子在南郊祭祀天地。本纪记祭礼结束后天气清明。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年正月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "829e7998-acd3-507d-a4cf-a17b2fcd4225"}, {"title": "朱元璋在南郊祭礼后谈体恤百姓", "description": "祭礼结束后，近臣称赞皇帝敬天。朱元璋说，上天把治理百姓的责任交给君主，要敬事上天，首先要体恤百姓。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年正月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d1a7bf0d-c3ae-52e3-80d3-7da06c275b4e"}, {"title": "明廷举行军事检阅", "description": "本纪记载，明廷于二月壬午检阅军伍。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年二月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1ac76d21-cc5b-519c-9460-793a51cf2304"}, {"title": "朱元璋行耕耤礼", "description": "朱元璋举行亲耕耤田的仪式。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年二月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6d00563c-9781-5352-866d-bb48de1207aa"}, {"title": "冯胜出松亭关并在大宁等地筑城", "description": "冯胜率军出松亭关，在大宁、宽河、会州和富峪筑城。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年三月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e6f041dd-e7a7-5dd8-96b8-247d2141899c"}, {"title": "周德兴在福建沿海筑城练兵", "description": "江夏侯周德兴在福建沿海筑城，训练军队防御倭寇。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年四月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a1da1909-e8ae-5c80-ae1c-f1a9dda5e3fc"}, {"title": "临江侯陈镛从征战死", "description": "临江侯陈镛随军出征，途中迷路，后来战死。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年六月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e74a87d1-6c00-5a7e-a0d6-d68c75e14751"}, {"title": "冯胜所部越过金山", "description": "本纪记载，六月癸卯冯胜率领的军队越过金山。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年六月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3b5be244-3573-5a3b-ade3-4c718d3c2c8a"}, {"title": "纳哈出归降明朝", "description": "本纪记载，纳哈出于六月丁未向明军投降。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年六月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bac5e076-80fa-5b7c-ae42-4ee2e0410d8d"}, {"title": "明军回程在金山遇伏，都督濮英战死", "description": "明军返回时停驻金山，负责殿后的都督濮英遭遇伏击，战死。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年闰六月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f84a7f20-74c2-507b-a110-4b49d6fbfed5"}, {"title": "冯胜被召回，蓝玉代理军务", "description": "朝廷收回冯胜的将军印并召他返回，命蓝玉代理军务。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年八月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "57b84876-96ac-59d9-9268-32e39f3187d5"}, {"title": "曹震在云南品甸屯田", "description": "景川侯曹震在云南品甸屯田。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "23df1e6c-a01d-5465-87b2-566eca50d54f"}, {"title": "纳哈出获封海西侯", "description": "明廷将归降的纳哈出封为海西侯。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年九月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bdda5327-b185-5246-af4a-67f8b5f8d8f4"}, {"title": "明廷设置大宁都指挥使司", "description": "朝廷设置大宁都指挥使司。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年九月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "147476cb-1ebd-5a04-bd3c-356263d184e0"}, {"title": "明廷将常茂安置龙州", "description": "朝廷将郑国公常茂安置到龙州。", "start_year": 1387, "end_year": 1387, "time_original": "洪武二十年九月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": 